#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s;
    cin >> s;

    string vowels = "aeiou";
    vector<int> first(32, -2);
    first[0] = -1;
    int mask = 0, best = 0;
    for (int i = 0; i < (int) s.size(); i++) {
        size_t j = vowels.find(s[i]);
        if (j != string::npos) mask ^= 1 << j;
        if (first[mask] != -2) best = max(best, i - first[mask]);
        else first[mask] = i;
    }
    cout << best << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        String vowels = "aeiou";
        int[] first = new int[32];
        Arrays.fill(first, -2);
        first[0] = -1;
        int mask = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            int j = vowels.indexOf(s.charAt(i));
            if (j >= 0) mask ^= 1 << j;
            if (first[mask] != -2) best = Math.max(best, i - first[mask]);
            else first[mask] = i;
        }
        System.out.println(best);
    }
}
